import{_ as r,C as s,o,c as i,j as a,a as n,E as d,a6 as l}from"./chunks/framework.BHBQfcoO.js";const v=JSON.parse('{"title":"LCARdS 2026.04.13.1","description":"Expanded elbow zones and the Preview Features opt-in.","frontmatter":{"version":"2026.04.13.1","date":"2026-04-13T00:00:00.000Z","status":"released","summary":"Expanded elbow zones and the Preview Features opt-in.","breaking":false},"headers":[],"relativePath":"releases/2026.04.13.1.md","filePath":"releases/2026.04.13.1.md"}'),c={name:"releases/2026.04.13.1.md"};function h(u,e,p,g,f,m){const t=s("ReleaseMeta");return o(),i("div",null,[e[0]||(e[0]=a("h1",{id:"lcards-2026-04-13-1",tabindex:"-1"},[n("LCARdS 2026.04.13.1 "),a("a",{class:"header-anchor",href:"#lcards-2026-04-13-1","aria-label":'Permalink to "LCARdS 2026.04.13.1"'},"​")],-1)),d(t),e[1]||(e[1]=l('<p>A bit of a smaller release that fixes issues a couple frontend issues, and with a bit more focus on the backend/internals to help support future features/requests.</p><h2 id="new-features" tabindex="-1">New Features <a class="header-anchor" href="#new-features" aria-label="Permalink to &quot;New Features&quot;">​</a></h2><h3 id="elbow-card-expanded-zone-definitions" tabindex="-1">Elbow Card - Expanded Zone Definitions <a class="header-anchor" href="#elbow-card-expanded-zone-definitions" aria-label="Permalink to &quot;Elbow Card - Expanded Zone Definitions&quot;">​</a></h3><p>Zone auto-calculation for elbow cards has been expanded with new configurations for L-corner (left and right) and open/contained presets. All standard zone names (<code>vertical_bar</code>, <code>horizontal_bar</code>, <code>body</code>, <code>full</code>, and layout-specific aliases like <code>left_bar</code>, <code>right_bar</code>) are now consistently defined across all elbow geometry variants. (<a href="https://github.com/snootched/lcards/issues/340" target="_blank" rel="noreferrer">#340</a>)</p><h3 id="preview-features-system" tabindex="-1"><em>Preview Features</em> System <a class="header-anchor" href="#preview-features-system" aria-label="Permalink to &quot;*Preview Features* System&quot;">​</a></h3><p>A new <strong>Preview Features</strong> toggle has been added to the LCARdS integration configuration (Settings → Devices &amp; Services → LCARdS → Configure).</p><p>New features are already included in the release: opting-in with this setting will surface their configuration across the UI so you can control them. Without it, the features operate behind the scenes with established defaults - you simply won&#39;t see the settings. To see which features are currently behind the gate - check the <em>Preview Features</em> section of the About tab in the LCARdS Config Panel.</p><blockquote><p><strong>Why a gate instead of a dev build?</strong> Preview features are functional and tested, but their config schema or UI may shift before they are promoted to stable. The gate lets you opt in knowing that small breaking changes could arrive in a subsequent release.</p></blockquote><h2 id="updates-fixes" tabindex="-1">Updates &amp; Fixes <a class="header-anchor" href="#updates-fixes" aria-label="Permalink to &quot;Updates &amp; Fixes&quot;">​</a></h2><ul><li><strong>Fix (Animations):</strong> <code>while</code>-condition lifecycle handling corrected: conditions now properly start/stop looping animations when the entity state changes without requiring a page reload. <code>check_on_load</code> now defaults to <code>true</code>, so a looping animation with a <code>while</code> condition activates immediately on card load if the condition is already met (<a href="https://github.com/snootched/lcards/issues/341" target="_blank" rel="noreferrer">#341</a>)</li><li><strong>Update (Config Panel):</strong> The Storage tab is now only shown to HA admin users. Non-admin users no longer see the backend storage explorer.</li></ul><h2 id="preview-features" tabindex="-1">Preview Features <a class="header-anchor" href="#preview-features" aria-label="Permalink to &quot;Preview Features&quot;">​</a></h2><h3 id="per-device-per-user-settings" tabindex="-1">Per-Device &amp; Per-User Settings <a class="header-anchor" href="#per-device-per-user-settings" aria-label="Permalink to &quot;Per-Device &amp; Per-User Settings&quot;">​</a></h3><p>A new fully scoped-settings system for the backend is included in this release. This enables persistent storage with APIs for per-user/per-device settings. The first feature to utilize this new system is the Sound system.</p><h4 id="per-device-per-user-sound" tabindex="-1">Per-Device &amp; Per-User Sound <a class="header-anchor" href="#per-device-per-user-sound" aria-label="Permalink to &quot;Per-Device &amp; Per-User Sound&quot;">​</a></h4><p>Sound settings can be configured independently per browser session and per HA user. A wall-mounted kiosk can run at lower volume than a desktop; a specific user can disable sounds entirely without affecting anyone else. All of this is configurable centrally from the Config Panel: no need to make changes from the target device.</p><h4 id="users-devices-management" tabindex="-1">Users &amp; Devices Management <a class="header-anchor" href="#users-devices-management" aria-label="Permalink to &quot;Users &amp; Devices Management&quot;">​</a></h4><p>Each browser/device receives a stable unique identity that persists across page reloads. Devices can be given friendly display names (&quot;Kitchen Tablet&quot;, &quot;Bedroom Tablet&quot;) for easy to use referencing.</p><p>A new <strong>Users &amp; Devices</strong> tab appears in the LCARdS Config Panel that provides a central view of all registered devices and users with stored scoped settings, and provides the ability to manage their overrides without needing to be on the target device.</p><h4 id="targeted-ha-services" tabindex="-1">Targeted HA Services <a class="header-anchor" href="#targeted-ha-services" aria-label="Permalink to &quot;Targeted HA Services&quot;">​</a></h4><p>All <code>lcards.*</code> HA services (alert modes, clear alert, reload page, log level) can now be targeted at specific devices or users rather than broadcasting to all sessions. Four targeting fields are supported:</p><ul><li><code>target_device_ids</code>: target by device/browser UUID</li><li><code>target_user_ids</code>: target by HA user ID</li><li><code>target_device_names</code>: target by friendly device name (case-insensitive, resolved server-side)</li><li><code>target_user_names</code>: target by HA user display name (case-insensitive, resolved server-side)</li></ul><p>Omitting all fields broadcasts to everyone: fully backward-compatible with existing automations.</p><h4 id="targeted-alert-modes" tabindex="-1">Targeted Alert Modes <a class="header-anchor" href="#targeted-alert-modes" aria-label="Permalink to &quot;Targeted Alert Modes&quot;">​</a></h4><p>Alert modes (red/yellow/blue alert etc.) can now be triggered on individual devices or users without changing the global alert state. A red alert on the kitchen tablet doesn&#39;t affect any other screen, and clearing it stays local.</p><hr><p>All changes: <a href="https://github.com/snootched/lcards/compare/2026.04.11.2...2026.04.13.1" target="_blank" rel="noreferrer">2026.04.11.2...2026.04.13.1</a></p>',26))])}const w=r(c,[["render",h]]);export{v as __pageData,w as default};
